# PostgreSQL-style dollar-quote delimiters: $$ or $tag$ where tag follows
# identifier rules (letters/digits/underscore, cannot start with a digit).
_DOLLAR_QUOTE_RE = re.compile(r"\$(?:[^\W\d]\w*)?\$", re.UNICODE)


def _iter_sql_chars(sql: str) -> Iterator[tuple[int, str, bool]]:
    """Iterate through SQL characters, tracking string literal context.

    Handles escape sequences (backslash), SQL-style doubled quotes,
    dollar-quoted strings ($$ ... $$ / $tag$ ... $tag$) and comments
    (-- line comments, /* block comments */).

    Yields:
        (index, char, outside_string) tuples where outside_string is True
        when the character is not inside a string literal, dollar-quoted
        string or comment.
    """
    in_single_quote = False
    in_double_quote = False
    dollar_delim: str | None = None
    i = 0

    while i < len(sql):
        char = sql[i]

        # Inside a dollar-quoted string: everything up to the matching
        # delimiter is literal text (semicolons, quotes, newlines included).
        if dollar_delim is not None:
            end = sql.find(dollar_delim, i + len(dollar_delim))
            if end == -1:
                # Unterminated dollar-quoted string: rest is literal.
                for offset in range(i, len(sql)):
                    yield (offset, sql[offset], False)
                return
            for offset in range(i, end + len(dollar_delim)):
                yield (offset, sql[offset], False)
            i = end + len(dollar_delim)
            dollar_delim = None
            continue

        if not in_single_quote and not in_double_quote:
            # Line comment: run to end of line (newline stays structural).
            if char == "-" and sql[i + 1 : i + 2] == "-":
                end = sql.find("\n", i)
                if end == -1:
                    for offset in range(i, len(sql)):
                        yield (offset, sql[offset], False)
                    return
                for offset in range(i, end):
                    yield (offset, sql[offset], False)
                i = end
                continue

            # Block comment: run to the closing */.
            if char == "/" and sql[i + 1 : i + 2] == "*":
                end = sql.find("*/", i + 2)
                if end == -1:
                    for offset in range(i, len(sql)):
                        yield (offset, sql[offset], False)
                    return
                for offset in range(i, end + 2):
                    yield (offset, sql[offset], False)
                i = end + 2
                continue

            # Start of a dollar-quoted string.
            if char == "$":
                match = _DOLLAR_QUOTE_RE.match(sql, i)
                if match:
                    dollar_delim = match.group(0)
                    yield (i, char, False)
                    i += 1
                    continue

